    spLadderDesc: 'التعزيزات كل أسبوعين، ومدة كل منها. لا ينخفض أي من العمودين أبدًا أثناء تسلقك، ويرتفع الإجمالي دائمًا.',
    spColUnlocks: 'يفتح',
