    spQuantityOnly: 'المزيد من الوصول، لا توجد طاقة جديدة',
    spRotationTitle: 'كيفية مشاركة الخانة',
    spRotationDesc: 'تدور الفتحة بدلاً من المسامير. عندما يتم تشغيل العديد من التعزيزات في وقت واحد، يتم منح كل مشاهد واحدًا، يتم ترجيحه حسب مستوى شارة المعزز — يتم عرض مستوى أعلى في كثير من الأحيان، ولا يزال الجميع يحصلون على النافذة التي دفعوا ثمنها. ما يشتريه التعزيز هو حصة من الصوت لعدد محدد من الدقائق، وليس امتلاك الجزء العلوي من الخلاصة فقط.',
    spCycleTitle: 'ساعة واحدة للجميع',
    spCycleDesc: 'الدورة هي أربعة عشر يومًا على مستوى المنصة، لذلك يتم إعادة تعبئة بدل الجميع في نفس اللحظة. لا شيء يتدحرج. قم بإلغاء الحجز قبل أن يبدأ وستعود الدقائق إلى الدورة التي دفعت لهم منها.',
    spSafetyTitle: 'ما لا يمكن أن يفعله التعزيز',
    spSafetyDesc: 'تتم إعادة فحص كل سحب مقابل المنشور كما هو في تلك اللحظة، لذلك فإن المنشور الذي تمت إزالته أو حظره أو وضع علامة عليه ناضجًا لا يصل أبدًا إلى تغذية شخص غريب. يتم رفض المنشورات الناضجة عند الحجز أيضًا، ولا يتم أبدًا منح دفعة لشخص قام بحظرك أو الشخص الذي قمت بتعزيزه.',
