    feeTierSubtitle: 'تخفيض الرسوم على أساس الشارة',
    feeTierDesc: 'يكافئ هيكل الرسوم الثوري لدينا حاملي رموز DeHub برسوم منصة مخفضة بشكل كبير. بدءًا من رسوم قياسية بنسبة 10 ٪، فإن كل فئة من فئات الشارات المكتسبة من خلال زيادة حيازات الرموز تخفض الرسوم بنسبة 0.69 ٪، لتصل في النهاية إلى 1 ٪ فقط لحاملي شارات Megalodon - وهو تخفيض بنسبة 99 ٪ في الرسوم لأعضاء مجتمعنا الأكثر تفانيًا.',
