    feeDisclaimer: 'إخلاء مسؤولية مهم عن الرسوم',
    feeDisclaimerDesc: 'تنطبق الرسوم فقط على خدمات معينة مثل الإكراميات والاشتراكات والدفع لكل مشاهدة ومكافآت Watch2earn. يمكن للمستخدمين إرسال الرموز المميزة إلى مستخدمين آخرين مجانًا عبر التطبيق والاستفادة من أدوات التجريد الخاصة بنا للقيام بذلك دون الحاجة إلى عنوان محفظة أو إدارة مفتاح خاص.',
