    intro1: 'كفريق مليء باللاعبين والبث، قمنا ببناء وإصدار عدد من ألعاب الأركيد الممتعة والمجانية ونعمل على أول لعبة رئيسية لنا، Last Chad Standing، أول لعبة MMA Battle Royale على الإطلاق، مع فريق من المطورين من أمثال Ubisoft بالإضافة إلى فريق مؤسس يشارك بشكل كبير مع نجوم UFC و Oktagon و PFL، بعد تصوير أفلام وثائقية مع أبطال مثل خورخي ماسفيدال، وتدريبهم تحت قيادة مدرب كونور ماكجريجور كافانا. تم تصوير الأفلام الوثائقية أيضًا من قبل لوك بارنات، رئيس غرفة الحرب في أندرو تيت والرامي السابق في UFC، نيابة عن DeHub.',
