    povrDesc4: 'يقوم برنامجنا، مع براءات الاختراع المعلقة، بذلك من خلال نظام تصنيف غير مسبوق من 13 مستوى إلى جانب شارات التحقق الخاصة بنا، والتي تم تسليط الضوء عليها في تسليط الضوء على الميزة السابقة.',
